-- App catalogue expansion, 2026-11-01.
-- Adds the six apps that previously existed only as hardcoded entries, so /apps
-- and every count render from CMS rows. Idempotent: upserted by slug, existing
-- CMS edits to other rows are untouched.
-- Not applied automatically: run only with owner approval.

INSERT INTO `apps` (`slug`, `name`, `tagline`, `role`, `year`, `platforms`, `genre`, `icon`, `screenshots`, `rating_value`, `rating_count`, `stack`, `links`, `summary`, `features`, `story`, `metrics`, `published`, `sort_order`) VALUES
  ('evlab', 'EVLAB', 'Electric mobility for rentals, leasing, and marketplace — one app for three business models.', 'Mobile Engineering Lead · Chalhoub Group', '2023 — 2026', '["iOS","Android"]', 'Mobility', '/media/apps/evlab/icon.webp', '[]', NULL, NULL, '["Flutter","Dart","Clean Architecture","Riverpod","REST APIs","Codemagic"]', '{"website":"https://www.ev-lab.io"}', 'An electric mobility platform for rentals, leasing, and marketplace, with the iOS and Android apps owned end to end — architecture, delivery, store releases, and production support.', '["Daily rentals, long-term leasing, and marketplace in one product","One account, payment, and authentication flow across all three models","Flutter apps on Clean Architecture with Riverpod","Secure REST APIs, analytics, and third-party SDK integrations","Codemagic CI/CD and store releases owned end to end"]', 'EVLAB carries three business models — daily rentals, long-term leasing, and a marketplace — inside one brand. Splitting them into separate apps would have tripled release overhead and split the customer record, so the mobile product shipped as one Flutter codebase with modular boundaries. I led mobile engineering at Chalhoub Group: architecture, secure API integration, CI/CD with Codemagic, release management, and production support through January 2026.', '[["3","Business models"],["2","Platforms"],["2023–26","Engagement"]]', 1, 15),
  ('good2go-loans', 'Good2Go Loans', 'Digital lending for New Zealand — onboarding, identity, and account access in one Flutter app.', 'Senior Flutter Developer · Beedev Solutions', '2019 — 2021', '["iOS","Android"]', 'Finance', '/media/apps/good2go/icon.webp', '[]', NULL, NULL, '["Flutter","Dart","Clean Architecture","SOLID","REST APIs","Push notifications"]', '{"website":"https://www.goodtogoloans.com.au"}', 'A digital lending app used by 50,000+ people across New Zealand — onboarding, authentication, account journeys, and store releases owned end to end.', '["Onboarding, identity, and eligibility journeys","Authentication, session handling, and account access","Account management and push notifications","REST API integrations with the lending platform","Android and iOS releases owned through production"]', 'Lending products earn trust in the first few minutes, so identity, eligibility, and account access were treated as core journeys rather than form screens. I built the Flutter app on Clean Architecture and SOLID boundaries, integrated the lending APIs, and owned both store pipelines through production. The product reached 50,000+ users across New Zealand, and the architecture became the base the team kept extending.', '[["50K+","Users in New Zealand"],["2","Platforms"],["2019–21","Engagement"]]', 1, 16),
  ('nakheel-marinas', 'Nakheel Marinas', 'A marina and lifestyle app delivered with a Flutter team on a fixed release train.', 'Lead Senior Software Engineer (Mobile) · Belong Interactive', '2022 — 2023', '["iOS","Android"]', 'Lifestyle', '/media/apps/nakheel/icon.webp', '[]', NULL, NULL, '["Flutter","Dart","REST APIs","Authentication","Analytics","Push notifications"]', '{}', 'A marina and lifestyle app shipped with a Flutter team under a fixed release train — 15,000+ downloads in its first month.', '["Marina and lifestyle content in one app","Authentication, notifications, and analytics integrated on schedule","Flutter architecture and standards shared across the team","Code review and production delivery","Fixed release train for a seasonal launch"]', 'Hospitality apps ship against deadlines that do not move: a season opens, a marina is announced, a campaign goes live. I led the Flutter team on architecture, standards, code review, and delivery, and integrated authentication, notifications, analytics, and third-party services on schedule. The app launched to 15,000+ downloads in its first month.', '[["15K+","First-month downloads"],["2","Platforms"],["2022–23","Engagement"]]', 1, 17),
  ('automover-tms', 'Automover TMS', 'Transport management for Australian fleet operators.', 'Full-stack engineer', NULL, '["Web"]', 'Logistics', '/media/apps/automover-tms/icon.webp', '[]', NULL, NULL, '[]', '{"website":"https://www.automover.com.au/"}', 'A transport management system for Australian fleet operators.', '[]', NULL, '[]', 1, 18),
  ('kokoro-michi', 'Kokoro Michi', 'An Android wellness app for daily practice and habit building.', 'Mobile engineer', NULL, '["Android"]', 'Health & Fitness', NULL, '[]', NULL, NULL, '[]', '{}', 'An Android wellness app for daily practice and habit building.', '[]', NULL, '[]', 1, 19),
  ('chuckleplay', 'ChucklePlay', 'A lightweight multi-platform IPTV player, open source on GitHub.', 'Creator · maintainer', '2026', '["Android","iOS","Web","Desktop"]', 'Entertainment', NULL, '[]', NULL, NULL, '["Flutter","Dart","M3U","Xtream Codes"]', '{"github":"https://github.com/hasanabbassorathiya/ChucklePlay"}', 'An open-source, lightweight multi-platform IPTV player built with Flutter — M3U and Xtream playlists, favourites and history, playlist switching, and remote-friendly navigation.', '["M3U and Xtream playlist import","Favourites and watch history","Playlist switching","TV remote navigation","Flutter builds for mobile, web, and desktop"]', 'An MIT-licensed Flutter project first published in January 2026, with builds for Android, iOS, web, Linux, macOS, and Windows. Distribution is source-only: there are no tagged releases yet.', '[["2026","Published"],["MIT","Licence"],["Source","Distribution"]]', 1, 20)
ON DUPLICATE KEY UPDATE `name` = VALUES(`name`), `tagline` = VALUES(`tagline`), `role` = VALUES(`role`), `year` = VALUES(`year`), `platforms` = VALUES(`platforms`), `genre` = VALUES(`genre`), `icon` = VALUES(`icon`), `screenshots` = VALUES(`screenshots`), `rating_value` = VALUES(`rating_value`), `rating_count` = VALUES(`rating_count`), `stack` = VALUES(`stack`), `links` = VALUES(`links`), `summary` = VALUES(`summary`), `features` = VALUES(`features`), `story` = VALUES(`story`), `metrics` = VALUES(`metrics`), `published` = VALUES(`published`), `sort_order` = VALUES(`sort_order`);

UPDATE `profile`
SET `v` = '[{"label":"Years Experience","value":6,"suffix":"+"},{"label":"App Profiles","value":21},{"label":"Client Engagements","value":3},{"label":"Good2Go Users","value":50,"suffix":"K+"}]'
WHERE `k` = 'stats_json';
